<template><view class="page"><nav-bar title="题目详情" :showBack="true" placeholder/><scroll-view scroll-y class="content"><view v-if="loading" class="state">正在加载...</view><view v-else-if="error" class="state" @click="load">加载失败，点击重试</view><template v-else><view class="card"><view class="tags"><text>{{question.questionType}}</text><text>{{question.difficulty}}</text></view><view class="info"><text>科目：{{question.subject||'-'}}</text><text>章节：{{question.chapter||'-'}}</text><text>知识点：{{question.knowledgePoint||'-'}}</text></view></view><view class="card"><text class="title">题目</text><text class="stem">{{question.content}}</text><view v-if="options.length" class="options"><text v-for="(op,i) in options" :key="i">{{String.fromCharCode(65+i)}}. {{op}}</text></view></view><view class="card answer"><text>正确答案：{{question.answer||'暂无'}}</text><text>答案解析：{{question.analysis||'暂无'}}</text></view><view class="card"><text>所属题库：{{question.bankName||'-'}}</text></view></template></scroll-view><view class="bottom"><button @click="favorite">{{question.favorited?'取消收藏':'收藏'}}</button><button @click="addToBank">加入题库组</button><button class="primary" :disabled="question.selected" @click="addToPaper">{{question.selected?'已加入':'加入试卷'}}</button></view></view></template>
<script>import NavBar from '@/components/nav-bar/nav-bar.vue';import{getQuestionDetail,favoriteQuestion,unfavoriteQuestion,listPaperBanks,addQuestionToBank,addPaperQuestion}from'@/api/paper.js';export default{components:{NavBar},data(){return{questionId:null,paperId:null,question:{},loading:false,error:false}},computed:{options(){if(!this.question.options)return[];if(Array.isArray(this.question.options))return this.question.options;try{return JSON.parse(this.question.options)}catch(e){return[]}}},onLoad(q){this.questionId=q.questionId;this.paperId=q.paperId||null;this.load()},methods:{async load(){this.loading=true;this.error=false;try{const r=await getQuestionDetail(this.questionId,this.paperId);this.question=r.data||{}}catch(e){this.error=true}finally{this.loading=false}},async favorite(){if(this.question.favorited)await unfavoriteQuestion(this.questionId);else await favoriteQuestion(this.questionId);this.question.favorited=!this.question.favorited},async addToBank(){const r=await listPaperBanks({visibility:'private'});const banks=r.data||[];if(!banks.length)return uni.showToast({title:'暂无私有题库组',icon:'none'});uni.showActionSheet({itemList:banks.map(b=>b.name),success:async e=>{await addQuestionToBank(banks[e.tapIndex].id,this.questionId);uni.showToast({title:'已加入题库组'})}})},async addToPaper(){if(!this.paperId)return uni.showToast({title:'请先创建试卷',icon:'none'});await addPaperQuestion(this.paperId,{questionId:Number(this.questionId),score:5,sourceType:'detail',sourceId:this.question.bankId});this.question.selected=true;uni.showToast({title:'已加入试卷'})}}}</script>
<style scoped>.page{min-height:100vh;background:#f5f8fc;padding-bottom:120rpx}.content{height:calc(100vh - 210rpx);padding:20rpx 24rpx;box-sizing:border-box}.card{background:#fff;border-radius:18rpx;padding:26rpx;margin-bottom:16rpx}.tags text{background:#eaf2ff;color:#4775e5;border-radius:12rpx;padding:7rpx 13rpx;margin-right:10rpx}.info text,.options text,.answer text{display:block;margin-top:14rpx;color:#59677b}.title{display:block;font-weight:700}.stem{display:block;line-height:1.7;margin-top:18rpx}.answer{background:#eef5ff}.state{text-align:center;color:#98a2b3;padding:120rpx}.bottom{position:fixed;bottom:0;left:0;right:0;background:#fff;display:flex;gap:10rpx;padding:16rpx 20rpx}.bottom button{flex:1;font-size:22rpx;border-radius:30rpx}.bottom .primary{background:#4d78e8;color:#fff}</style>
